/** A simple variable store: numbers, booleans and strings only (deterministic). */
export type VariableValue = number | boolean | string;
export type VariableStore = Record<string, VariableValue>;

/**
 * Effects applied when a choice is taken.
 * - numeric value: delta, added to the current numeric value (missing vars start at 0)
 * - boolean / string value: the variable is set to that value
 */
export type Effects = Record<string, VariableValue>;

/** A condition expression evaluated against the variable store. */
export type Condition = string;

export interface Choice {
  /** Text shown to the player. */
  text: string;
  /** Id of the passage this choice leads to. Must exist in the story. */
  target: string;
  /** Optional condition; choice is only offered when it evaluates truthy. */
  condition?: Condition;
  /** Optional effects applied to the store when chosen. */
  effects?: Effects;
}

export interface Passage {
  id: string;
  text: string;
  choices: Choice[];
  /** Endings have no outgoing choices. */
  ending?: boolean;
}

export interface Story {
  title: string;
  start: string;
  passages: Passage[];
}

