import type { VariableStore } from "./types";

/**
 * Tiny, safe condition evaluator.
 *
 * Grammar (recursive descent, no eval / no Function):
 *   or     := and ("||" and)*
 *   and    := cmp ("&&" cmp)*
 *   cmp    := unary (("==" | "!=" | ">=" | "<=" | ">" | "<") unary)?
 *   unary  := "!" unary | primary
 *   primary:= NUMBER | STRING | "true" | "false" | IDENT | "(" or ")"
 *
 * Identifiers resolve against the variable store; unknown variables are
 * `undefined` (falsy). Relational operators require two numbers and evaluate
 * to false otherwise. Pure function of (expr, vars): fully deterministic.
 */

type TokenType = "number" | "string" | "ident" | "op";
interface Token {
  type: TokenType;
  value: string;
}

const TWO_CHAR_OPS = ["==", "!=", ">=", "<=", "&&", "||"] as const;
const ONE_CHAR_OPS = "()!=<>".split("");

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i]!;
    if (/\s/.test(c)) {
      i++;
      continue;
    }
    if (/[0-9]/.test(c)) {
      let j = i;
      while (j < src.length && /[0-9.]/.test(src[j]!)) j++;
      tokens.push({ type: "number", value: src.slice(i, j) });
      i = j;
      continue;
    }
    if (c === '"' || c === "'") {
      const quote = c;
      let j = i + 1;
      let str = "";
      while (j < src.length && src[j] !== quote) {
        if (src[j] === "\\") j++; // skip escaped char; take next literally
        str += src[j];
        j++;
      }
      if (j >= src.length) throw new Error(`Unterminated string literal in condition: ${src}`);
      tokens.push({ type: "string", value: str });
      i = j + 1;
      continue;
    }
    if (/[A-Za-z_]/.test(c)) {
      let j = i;
      while (j < src.length && /[A-Za-z0-9_]/.test(src[j]!)) j++;
      tokens.push({ type: "ident", value: src.slice(i, j) });
      i = j;
      continue;
    }
    const two = src.slice(i, i + 2);
    if ((TWO_CHAR_OPS as readonly string[]).includes(two)) {
      tokens.push({ type: "op", value: two });
      i += 2;
      continue;
    }
    if (ONE_CHAR_OPS.includes(c)) {
      tokens.push({ type: "op", value: c });
      i += 1;
      continue;
    }
    throw new Error(`Unexpected character ${JSON.stringify(c)} in condition: ${src}`);
  }
  return tokens;
}

class Parser {
  private pos = 0;
  constructor(
    private readonly tokens: Token[],
    private readonly vars: VariableStore,
    private readonly src: string,
  ) {}

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  private eat(op: string): boolean {
    const t = this.peek();
    if (t && t.type === "op" && t.value === op) {
      this.pos++;
      return true;
    }
    return false;
  }

  parse(): unknown {
    const result = this.parseOr();
    if (this.pos !== this.tokens.length) {
      throw new Error(`Unexpected trailing token in condition: ${this.src}`);
    }
    return result;
  }

  private parseOr(): unknown {
    let left = this.parseAnd();
    while (this.eat("||")) {
      const right = this.parseAnd();
      left = truthy(left) || truthy(right);
    }
    return left;
  }

  private parseAnd(): unknown {
    let left = this.parseCmp();
    while (this.eat("&&")) {
      const right = this.parseCmp();
      left = truthy(left) && truthy(right);
    }
    return left;
  }

  private parseCmp(): unknown {
    const left = this.parseUnary();
    const t = this.peek();
    if (t && t.type === "op" && [">", "<", ">=", "<=", "==", "!="].includes(t.value)) {
      this.pos++;
      const right = this.parseUnary();
      return compare(t.value, left, right);
    }
    return left;
  }

  private parseUnary(): unknown {
    if (this.eat("!")) return !truthy(this.parseUnary());
    return this.parsePrimary();
  }

  private parsePrimary(): unknown {
    const t = this.peek();
    if (!t) throw new Error(`Unexpected end of condition: ${this.src}`);
    if (t.type === "number") {
      this.pos++;
      return Number(t.value);
    }
    if (t.type === "string") {
      this.pos++;
      return t.value;
    }
    if (t.type === "ident") {
      this.pos++;
      if (t.value === "true") return true;
      if (t.value === "false") return false;
      return this.vars[t.value];
    }
    if (t.value === "(") {
      this.pos++;
      const inner = this.parseOr();
      if (!this.eat(")")) throw new Error(`Missing ")" in condition: ${this.src}`);
      return inner;
    }
    throw new Error(`Unexpected token ${JSON.stringify(t.value)} in condition: ${this.src}`);
  }
}

function truthy(v: unknown): boolean {
  return Boolean(v);
}

function compare(op: string, a: unknown, b: unknown): boolean {
  switch (op) {
    case "==":
      return a === b;
    case "!=":
      return a !== b;
  }
  // Relational operators are numeric-only; anything else is simply false
  // (deterministic, no exceptions during play).
  if (typeof a !== "number" || typeof b !== "number") return false;
  switch (op) {
    case ">":
      return a > b;
    case "<":
      return a < b;
    case ">=":
      return a >= b;
    case "<=":
      return a <= b;
    default:
      throw new Error(`Unknown comparison operator: ${op}`);
  }
}

/** Evaluate a condition expression against a variable store. Never uses eval(). */
export function evaluateCondition(condition: string, vars: VariableStore): boolean {
  return truthy(new Parser(tokenize(condition), vars, condition).parse());
}

