import type { Effects, VariableStore } from "./types";

/**
 * Apply effects to the store, mutating a copy and returning it (pure with
 * respect to the input store when used via the engine).
 * - numeric effect: delta added to the current numeric value (default 0)
 * - boolean/string effect: variable is set to that value
 */
export function applyEffects(vars: VariableStore, effects: Effects | undefined): VariableStore {
  if (!effects) return vars;
  for (const [key, value] of Object.entries(effects)) {
    if (typeof value === "number") {
      const current = typeof vars[key] === "number" ? (vars[key] as number) : 0;
      vars[key] = current + value;
    } else {
      vars[key] = value;
    }
  }
  return vars;
}

