import type { Choice, Passage, Story, VariableStore } from "./types";
import { evaluateCondition } from "./evaluator";
import { applyEffects } from "./effects";

/** A choice that is currently offered to the player (condition passed). */
export interface OfferedChoice {
  index: number;
  choice: Choice;
}

export interface Step {
  from: string;
  via: string;
  to: string;
}

/**
 * Deterministic choice-based story engine. All methods are pure functions of
 * the current state; no randomness, no time, no eval.
 */
export class StoryEngine {
  readonly story: Story;
  private vars: VariableStore;
  private currentId: string;
  private history: Step[] = [];

  constructor(story: Story, initialVars: VariableStore = {}) {
    this.story = story;
    this.vars = { ...initialVars };
    const start = story.passages.find((p) => p.id === story.start);
    if (!start) throw new Error(`Story start passage not found: ${story.start}`);
    this.currentId = start.id;
  }

  get current(): Passage {
    const p = this.story.passages.find((x) => x.id === this.currentId);
    if (!p) throw new Error(`Current passage missing: ${this.currentId}`);
    return p;
  }

  get currentId$(): string {
    return this.currentId;
  }

  /** Snapshot of the variable store (defensive copy). */
  get variables(): VariableStore {
    return { ...this.vars };
  }

  /** Read-only transcript of steps taken so far. */
  get steps(): readonly Step[] {
    return [...this.history];
  }

  isEnding(): boolean {
    return this.current.ending === true;
  }

  /** Choices whose condition (if any) passes against the current store. */
  availableChoices(): OfferedChoice[] {
    return this.current.choices
      .map((choice, index) => ({ index, choice }))
      .filter(({ choice }) => !choice.condition || evaluateCondition(choice.condition, this.vars));
  }

  /**
   * Take a choice by its index into the full choices array of the current
   * passage. Throws if the choice does not exist or its condition fails.
   */
  choose(index: number): void {
    const passage = this.current;
    const choice = passage.choices[index];
    if (!choice) throw new Error(`No choice at index ${index} in passage ${passage.id}`);
    if (!choice.condition || evaluateCondition(choice.condition, this.vars)) {
      applyEffects(this.vars, choice.effects);
      const target = this.story.passages.find((p) => p.id === choice.target);
      if (!target) throw new Error(`Choice target passage not found: ${choice.target}`);
      this.history.push({ from: passage.id, via: choice.text, to: target.id });
      this.currentId = target.id;
      return;
    }
    throw new Error(`Condition not met for choice "${choice.text}" in ${passage.id}`);
  }
}

