import type { Story } from "./types";

/** Static story validation. Returns a list of problems (empty = valid). */
export function validateStory(story: Story): string[] {
  const errors: string[] = [];
  const ids = new Set<string>();

  if (!story.start) errors.push("Story has no start passage");

  for (const passage of story.passages) {
    if (ids.has(passage.id)) errors.push(`Duplicate passage id: ${passage.id}`);
    ids.add(passage.id);
    if (!passage.ending && passage.choices.length === 0) {
      errors.push(`Non-ending passage with no choices: ${passage.id}`);
    }
  }

  if (story.start && !ids.has(story.start)) {
    errors.push(`Start passage does not exist: ${story.start}`);
  }

  for (const passage of story.passages) {
    for (const choice of passage.choices) {
      if (!ids.has(choice.target)) {
        errors.push(`Passage "${passage.id}" choice "${choice.text}" -> missing target "${choice.target}"`);
      }
      if (passage.ending && passage.choices.length > 0) {
        // checked below via generic rule; keep message single-source
      }
    }
  }

  for (const passage of story.passages) {
    if (passage.ending && passage.choices.length > 0) {
      errors.push(`Ending passage must have no choices: ${passage.id}`);
    }
  }

  return errors;
}

