import type { Story } from "./types";

/**
 * "The Gilded Crown" — a 10-passage story with one gated good ending:
 * reaching the coronation requires gold >= 10 AND met_king.
 */
export const gildedCrown: Story = {
  title: "The Gilded Crown",
  start: "village_square",
  passages: [
    {
      id: "village_square",
      text: "Dawn breaks over the village square. Rumors swirl of the old king's return to the castle atop the hill.",
      choices: [
        { text: "Wander over to the market stalls.", target: "market" },
        { text: "Slip into the whispering forest instead.", target: "forest" },
      ],
    },
    {
