import { describe, it, expect } from "vitest";
import { StoryEngine } from "../src/engine";
import { validateStory } from "../src/validate";
import { gildedCrown } from "../src/story";
import { evaluateCondition } from "../src/evaluator";
import type { VariableStore } from "../src/types";

/** Find a choice index in the current passage by its exact text. */
function choiceIndex(engine: StoryEngine, text: string): number {
  const hit = engine.current.choices.findIndex((c) => c.text === text);
  if (hit === -1) throw new Error(`Choice not offered in ${engine.current.id}: ${text}`);
  return hit;
}

describe("gated good ending", () => {
  it("scripted gold-gathering path reaches the coronation with the exact expected state", () => {
    const engine = new StoryEngine(gildedCrown);
    expect(engine.currentId$).toBe("village_square");

    engine.choose(choiceIndex(engine, "Wander over to the market stalls."));
    expect(engine.currentId$).toBe("market");

    engine.choose(choiceIndex(engine, "Head for the docks to earn some coin."));
    expect(engine.currentId$).toBe("docks");

    // Two shifts: +5 gold each.
    engine.choose(choiceIndex(engine, "Work another shift hauling crates. (+5 gold)"));
    engine.choose(choiceIndex(engine, "Work another shift hauling crates. (+5 gold)"));
    expect(engine.variables).toEqual({ gold: 10 });

    engine.choose(choiceIndex(engine, "Pocket your earnings and visit the tavern."));
    engine.choose(choiceIndex(engine, "Make your way up to the castle gate."));

    // Meeting the king sets met_king: true at the gate.
    engine.choose(choiceIndex(engine, "Announce yourself and request an audience."));
    expect(engine.currentId$).toBe("throne_room");
    expect(engine.variables).toEqual({ gold: 10, met_king: true });

    engine.choose(
      choiceIndex(engine, "Follow the chamberlain into the audience hall."),
    );

    // The gated choice is visible now and leads to the good ending.
    const offered = engine.availableChoices().map(({ choice }) => choice.text);
    expect(offered).toContain("Pledge your fortune to the crown and be honored.");
    engine.choose(choiceIndex(engine, "Pledge your fortune to the crown and be honored."));

    expect(engine.currentId$).toBe("coronation");
    expect(engine.isEnding()).toBe(true);
    // Exact final variable state — nothing more, nothing less.
    expect(engine.variables).toEqual({ gold: 10, met_king: true });
    expect(engine.steps.map((s) => s.to)).toEqual([
      "market",
      "docks",
      "docks",
      "docks",
      "tavern",
      "castle_gate",
      "throne_room",
      "audience_hall",
      "coronation",
    ]);
  });
});

describe("gating", () => {
  it("a path that skips the king cannot see the gated choice", () => {
    const engine = new StoryEngine(gildedCrown);
    // Sneak route: never meet the king, but still gather plenty of gold.
    engine.choose(choiceIndex(engine, "Slip into the whispering forest instead."));
    expect(engine.currentId$).toBe("forest");
    engine.choose(choiceIndex(engine, "Turn back to the safety of the square."));
    engine.choose(choiceIndex(engine, "Wander over to the market stalls."));
    engine.choose(choiceIndex(engine, "Head for the docks to earn some coin."));
    engine.choose(choiceIndex(engine, "Work another shift hauling crates. (+5 gold)"));

    // Give extra gold directly so only the king requirement is missing.
    engine.variables; // no mutation via snapshot
    const sneaky = new StoryEngine(gildedCrown, { gold: 50 });
    sneaky.choose(choiceIndex(sneaky, "Slip into the whispering forest instead."));
    sneaky.choose(choiceIndex(sneaky, "Crawl through the tunnel straight into the audience hall."));
    expect(sneaky.currentId$).toBe("audience_hall");

    const offeredTexts = sneaky.availableChoices().map(({ choice }) => choice.text);
    expect(offeredTexts).not.toContain("Pledge your fortune to the crown and be honored.");
    expect(offeredTexts).toEqual(["Slip away before anyone notices you."]);
    // And the raw choices array still contains it — it is gated by condition,
    // not removed from the story data.
    expect(sneaky.current.choices.some((c) => c.condition === "gold >= 10 && met_king")).toBe(true);

    // The only available path is the plain ending.
    sneaky.choose(0);
    expect(sneaky.currentId$).toBe("leave_town");
    expect(sneaky.isEnding()).toBe(true);

    void engine; // scripted walk above stayed valid throughout
  });

  it("evaluator gates on both variables independently", () => {
    expect(evaluateCondition("gold >= 10 && met_king", { gold: 10, met_king: true })).toBe(true);
    expect(evaluateCondition("gold >= 10 && met_king", { gold: 10, met_king: false })).toBe(false);
    expect(evaluateCondition("gold >= 10 && met_king", { gold: 9, met_king: true })).toBe(false);
    expect(evaluateCondition("gold >= 10 && met_king", {})).toBe(false); // unknown vars are falsy
  });
});

describe("static validation", () => {
  it("story is valid: every referenced target exists", () => {
    expect(validateStory(gildedCrown)).toEqual([]);

    // Every choice target appears among passage ids.
    const ids = new Set(gildedCrown.passages.map((p) => p.id));
    for (const passage of gildedCrown.passages) {
      for (const choice of passage.choices) {
        expect(ids.has(choice.target), `${passage.id} -> ${choice.target}`).toBe(true);
      }
    }
    // Start exists; endings have no choices; non-endings are not dead ends.
    expect(ids.has(gildedCrown.start)).toBe(true);
    for (const passage of gildedCrown.passages) {
      if (passage.ending) expect(passage.choices).toHaveLength(0);
      else expect(passage.choices.length).toBeGreaterThan(0);
    }
    // Exactly 10 passages as authored.
    expect(gildedCrown.passages).toHaveLength(10);
  });

  it("validator reports broken stories", () => {
    const broken = {
      title: "broken",
      start: "a",
      passages: [
        { id: "a", text: "", choices: [{ text: "go", target: "ghost" }] },
        { id: "b", text: "", ending: true, choices: [{ text: "x", target: "a" }] },
      ],
    };
    const errors = validateStory(broken);
    expect(errors.some((e) => e.includes('missing target "ghost"'))).toBe(true);
    expect(errors.some((e) => e.includes("Ending passage must have no choices"))).toBe(true);
  });
});

describe("determinism", () => {
  it("identical scripts produce identical transcripts and states", () => {
    const runScript = (): { ids: string[]; vars: VariableStore; steps: string[] } => {
      const engine = new StoryEngine(gildedCrown);
      const script = [
        "Wander over to the market stalls.",
        "Head for the docks to earn some coin.",
        "Work another shift hauling crates. (+5 gold)",
        "Work another shift hauling crates. (+5 gold)",
        "Pocket your earnings and visit the tavern.",
        "Make your way up to the castle gate.",
        "Announce yourself and request an audience.",
        "Follow the chamberlain into the audience hall.",
        "Pledge your fortune to the crown and be honored.",
      ];
      for (const text of script) engine.choose(choiceIndex(engine, text));
      return {
        ids: engine.steps.map((s) => s.to),
        vars: engine.variables,
        steps: engine.steps.map((s) => `${s.from} --${s.via}--> ${s.to}`),
      };
    };
    const a = runScript();
    const b = runScript();
    expect(a).toEqual(b);
    expect(a.vars).toEqual({ gold: 10, met_king: true });
  });
});

